 * @param updatedAt    最近一次计时修订时间，Unix毫秒时间戳
 */
public record RunnerRow(
        long id,
        String raceId,
        String bib,
        Long finishTimeMs,
        long createdAt,
        long updatedAt
) implements ResultCalculator.RunnerView {
}
package com.example.starter.race.persistence;

import com.example.starter.race.domain.RaceStatus;

/**
 * race 表行记录。
 *
 * @param raceId    赛事ID，全局唯一
 * @param version   版本号，从1开始
 * @param status    赛事状态
 * @param createdAt 创建时间，Unix毫秒时间戳
 */
public record RaceRow(String raceId, int version, RaceStatus status, long createdAt) {
}
package com.example.starter.race.domain;

/**
 * 赛事状态：OPEN-开放可写；SEALED-已封榜，只读。
 */
public enum RaceStatus {
    OPEN,
    SEALED
}
package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 登记选手请求；不传 finishTimeMs 时该选手计时缺失（UNTIMED）。
 *
 * @param bib             参赛号，赛事内唯一
 * @param finishTimeMs    原始完赛耗时（毫秒，1~86400000）；可空表示暂未计时
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RegisterRunnerRequest(
        @NotBlank String bib,
        @Positive Long finishTimeMs,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}
package com.example.starter.race.api;

import com.example.starter.race.domain.RaceStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 成绩榜响应：即时成绩或封榜只读快照。
 *
 * @param raceId   赛事ID
 * @param version  榜单对应的版本号
 * @param status   OPEN / SEALED
 * @param sealedAt 封榜时间，Unix毫秒时间戳；未封榜为 null
 * @param entries  按展示顺序排列的成绩条目
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record StandingResponse(
        String raceId,
        int version,
        RaceStatus status,
        Long sealedAt,
        List<ResultEntryResponse> entries
) {
}

