            long now = clock.millis();
            try {
                repository.insertCategory(raceId, request.categoryCode(), request.capacity(), now);
            } catch (DuplicateKeyException ex) {
                throw new ConflictException("组别已存在: " + request.categoryCode());
            }
            CategoryRow category = repository.findCategory(raceId, request.categoryCode()).orElseThrow();
            return ServiceResult.created(ResponseMapper.toCategoryResponse(category));
