                throw new ConflictException("目标组别已封榜: " + request.targetCategoryCode());
            }
            if (request.targetCategoryCode().equals(runner.categoryCode())) {
                throw new UnprocessableEntityException("选手已在目标组别: " + request.targetCategoryCode());
