private CategoryStandingResponse computeCategoryStanding(String raceId, String categoryCode, int version) {
    CategoryRow category = repository.findCategory(raceId, categoryCode).orElseThrow();
    List<RunnerRow> runners = repository.findActiveRunnersByCategory(raceId, categoryCode);
    Set<String> bibs = runners.stream().map(RunnerRow::bib).collect(toSet());
    List<PenaltyRow> penalties = repository.findPenalties(raceId).stream().filter(p -> bibs.contains(p.bib())).toList();
    List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
    List<CheckpointTimingRow> timings = repository.findAllTimings(raceId).stream().filter(t -> bibs.contains(t.bib())).toList();
    List<ResultEntry> entries = ResultCalculator.compute(runners, penalties, checkpoints, timings);
    return new CategoryStandingResponse(raceId, categoryCode, version, category.status(), null,
        entries.stream().map(ResponseMapper::toEntryResponse).toList());
}
