```java
private CategorySnapshotRow buildCategorySnapshot(String raceId, String categoryCode, int version, long now) {
    CategoryStandingResponse standing = computeCategoryStanding(raceId, categoryCode, version);
    List<CategorySnapshotEntryRow> entries = new ArrayList<>();
    int order = 0;
    for (ResultEntryResponse e : standing.entries()) {
        entries.add(new CategorySnapshotEntryRow(raceId, categoryCode, e.bib(), e.rank(), e.status(), e.finishTimeMs(), e.penaltyMs(), e.totalTimeMs(), order++));
    }
    return new CategorySnapshotRow(raceId, categoryCode, version, now, entries);
}
