    void 主流程_申请批准后迁移并重算来源与目标组别排名() {
        createRace();
        createCategory("A", 3);
        createCategory("B", 3);
        register("a", 1000L, "A");
        register("b", 2000L, "A");
        register("c", 1500L, "B");
